// 从服务器环境中读取兼容消息接口的配置。
const { MODEL_API_URL, MODEL_API_KEY, MODEL_ID } = process.env

if (!MODEL_API_URL || !MODEL_API_KEY || !MODEL_ID) {
  throw new Error('缺少模型 API 配置')
}

// 发送一次请求，并限制网络等待时间。
const response = await fetch(MODEL_API_URL, {
  method: 'POST',
  headers: {
    Authorization: `Bearer ${MODEL_API_KEY}`,
    'Content-Type': 'application/json'
  },
  body: JSON.stringify({
    model: MODEL_ID,
    messages: [
      { role: 'system', content: '用中文安排轻松的行程，不要编造营业时间。' },
      { role: 'user', content: '周末去杭州两天，带老人，少走路，帮我安排一份行程。' }
    ]
  }),
  signal: AbortSignal.timeout(30_000)
})

if (!response.ok) {
  throw new Error(`模型请求失败： ${response.status}`)
}

// 先查看服务响应的结构，再提取生成的文本。
const result = await response.json()
console.log(result)
